# Slagstorm (FDN) -- Choose one --
#  * Slagstorm deals 3 damage to each creature.  (ZNR Cinderclasm's B6-kicker-instead-suffix "each
#      creature" atom: ALL TYPE_EQ Creature, any controller), 3.
#  * Slagstorm deals 3 damage to each player.    (the each-opponent damage of Firebrand Archer and
#      Storm Caller over Zone(PLAYER, ANY): every player, you included), 3.
abilities = [
    SpellAbility(
        kind=SpellKind.SORCERY,
        effect=Choose(
            count=QConst(value=1),
            options=(
                A(Verb.DEAL_DAMAGE, {
                    'amount': QConst(value=3),
                    'target': Selector(
                        count=QUnbounded(),
                        mode=SelectorMode.ALL,
                        filter=FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                        zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                    ),
                }),
                A(Verb.DEAL_DAMAGE, {
                    'amount': QConst(value=3),
                    'target': Selector(
                        count=QUnbounded(),
                        mode=SelectorMode.ALL,
                        filter=FAnd(children=()),
                        zones=(Zone(kind=ZoneKind.PLAYER, controller=ControllerRef.ANY),),
                    ),
                }),
            ),
        ),
    ),
]
